      // 입력이 허공에 간다. 컨트롤이 숨겨진 커스텀 UI(스타일된 라디오 등)에서는 label 을 그대로 둔다.
      if (tag === 'label') { var ctl = null; try { ctl = el.control; } catch (e) {} if (ctl && !ctl.disabled && visible(ctl)) continue; }
