  return new Promise(function(resolve){
    var prev = rect();
    function step(){
      var cur = rect();
      var stable = Math.abs(cur.x - prev.x) < 1 && Math.abs(cur.y - prev.y) < 1;
      if (stable || Date.now() > deadline) { resolve(finish(cur)); return; }
      prev = cur;
      requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  });
})()
`, true)) as { x: number; y: number; name: string; w: number; h: number; vw: number; vh: number; occluded: boolean } | RefFail | null
  } catch { return null }
}

