    // 이 속성에 "제목"·"내용을 입력하세요" 같은 안내를 담는다.
    var n = el.getAttribute('aria-label') || el.getAttribute('placeholder') || el.getAttribute('data-placeholder') || el.getAttribute('aria-placeholder') || '';
