      // 위 요소 스캔에 안 잡히는데, 파일 입력이 아예 없는 업로드 UI(틱톡식)에서는 유일한 첨부 경로다.
      // 텍스트로만 좁게 인식해 잡음을 만들지 않는다(드래그&드롭 안내 문구는 매우 특징적).
      if (!TAKEN.has(a) && out.length < MAX) {
