        // (문구 없이 아이콘만 있는 드롭존이 흔하므로 ②③ 이 필요하다. "dropdown" 오탐은 토큰 매칭으로 배제.)
        var byText = !!atxt && atxt.length <= 80 && DROP_RE.test(atxt);
