  var listHint = null;
  try {
    var sc = {}; var alln = document.querySelectorAll('*'); var L = Math.min(alln.length, 3000);
    for (var q = 0; q < L; q++) {
      var e2 = alln[q];
      var cn = (e2.className && typeof e2.className === 'string') ? e2.className.trim().split(/\\s+/)[0] : '';
