  // 업로드·인코딩 진행 상태 — progressbar 의 aria 값과 "업로드 중/처리 중 NN%" 문구를 모은다.
  // (영상 업로드는 첨부 후 수 분이 걸린다. 이 신호가 없으면 완료 여부를 추측하게 되고, 미완 상태로 게시된다.)
  var progress = '';
  try {
    var bars = document.querySelectorAll('[role=progressbar], progress');
