    var pm = bt0.match(/(업로드\\s*중[^\\n]{0,40}|처리\\s*중[^\\n]{0,40}|uploading[^\\n]{0,40}|processing[^\\n]{0,40}|\\d{1,3}\\s*%[^\\n]{0,30})/i);
