  var bodyText = (document.body ? document.body.innerText : '') || '';
  bodyText = bodyText.replace(/\\n{3,}/g, '\\n\\n').trim();
  return {
    url: location.href,
    title: document.title || '',
    text: bodyText.slice(0, ${maxText}),
    truncated: bodyText.length > ${maxText},
