  function isSecret(el) {
    var t = (el.getAttribute('type') || '').toLowerCase();
    if (t === 'password') return true;
    var ac = (el.getAttribute('autocomplete') || '').toLowerCase();
    return ac.indexOf('password') >= 0 || ac.indexOf('cc-') === 0 || ac === 'one-time-code';
