      try {
        var lb = (el.labels && el.labels[0]) || (el.closest ? el.closest('label') : null);
        // 값 문자열을 치환해 빼는 방식은 짧은 값("i")이 라벨 글자를 훼손한다 → 컨트롤 자신을 뺀 자식 노드 텍스트만 모은다.
