cd "C:\Users\molma\Desktop\하네스\browser-build" && python - <<'PY'
import io
p='app/main/features/ai/agent.ts'
s=io.open(p,encoding='utf-8').read(); o=s

# allowedHosts must be mutable (request_scope 로 사용자가 명시 승인하면 넓어진다)
s=s.replace("  const allowedHosts = params.allowedHosts",
            "  // 사용자가 request_scope 를 **명시 승인**했을 때만 넓어진다(자동 확대 금지).\n  let allowedHosts = params.allowedHosts ? [...params.allowedHosts] : undefined",1)

# 챌린지 감지 — 관찰 직후, LLM 호출 전. 여기 두는 이유: 모델을 부르기 전에 끊어야 예산이 안 탄다.
old = """      emit({ type: 'observe', step, url: obs.url, title: obs.title, elements: obs.elements.length, vision: !!shot })
"""
new = """      emit({ type: 'observe', step, url: obs.url, title: obs.title, elements: obs.elements.length, vision: !!shot })

      // ===== 로그인 / CAPTCHA 화면 → 사람에게 넘기기 =====
      // 이 화면 앞에서는 에이전트가 원리적으로 할 수 있는 게 없다. 예전에는 같은 화면을 보며 단계·모델 호출을
      // 다 태운 뒤에야 막힘 감지로 겨우 물었다. 이제 **모델을 부르기 전에** 멈춘다(예산 0 소모).
      // CAPTCHA 를 풀거나 우회하지 않는다 — 사용자가 직접 처리한 뒤 "계속" 이라고 하면 이어간다.
      {
        const ch: ChallengeVerdict | null = detectChallenge(obs, challengeResolved)
        if (ch) {
          const askP = waitAsk(reqId) // 대기자를 emit 전에 등록(배치 동기 응답 대비)
          emit({ type: 'challenge', kind: ch.kind, message: ch.reason, evidence: ch.evidence, url: obs.url })
          emit({ type: 'ask', message: ch.reason, challenge: ch.kind })
          const answer = await askP
          if (cancelledSet.has(reqId)) { emit({ type: 'cancelled' }); return }
          if (answer == null) {
            emit({ type: 'done', message: `${ch.kind === 'captcha' ? '사람 확인(CAPTCHA)' : '로그인'} 화면에서 중단했습니다 — 직접 처리하신 뒤 이어가기를 눌러 주세요.`, needsUser: true })
            return
          }
          // 사용자가 처리했다고 알려 줬다 → 같은 화면에서 다시 묻지 않는다. 다시 관찰부터(단계 소모 없음).
          challengeResolved.add(ch.key)
          emit({ type: 'answer', text: answer })
          pendingPrefix = `사용자가 ${ch.kind === 'captcha' ? '사람 확인' : '로그인'} 화면을 직접 처리했습니다: ${answer}`
          needVision = true
          step--
          continue
        }
      }
"""
assert old in s
s=s.replace(old,new,1)

io.open(p,'w',encoding='utf-8').write(s)
print('ok')
PY
