1220-      // 결제·삭제가 조용히 실행되는 것이 이 게이트의 가장 큰 사고 경로였다.
1221-      const needConfirm = risk.level === 'critical' || (risk.level === 'confirm' && !autoApprove)
1222-      if (needConfirm) {
1223-        const gateLabel = risk.reason ? `${label} — ${risk.reason}` : label
1224-        const gateP = waitConfirm(reqId) // 대기자를 emit 전에 등록(배치 동기 승인/거부 대비)
1225:        emit({ type: 'confirm', label: gateLabel, risk: risk.level, critical: risk.level === 'critical' })
1226-        const okGate = await gateP
1227-        // 승인과 취소가 거의 동시에 도착하는 경합. 승인이 먼저 처리돼 리졸버를 깨우더라도, **이미 보내진**
1228-        // 취소가 처리될 기회를 한 턴 준 뒤 다시 확인한다. 정책: **취소가 이긴다** — 이미 나간 동작은
