import io,re
p='build/verify-frames-cdp.mjs'
s=io.open(p,encoding='utf-8').read()

start = s.index("    // ───────────────────────────────────────────────────────────────\n    // F5 — 프레임 재로드")
end = s.index("    // ───────────────────────────────────────────────────────────────\n    // F6 —")
new = '''    // ───────────────────────────────────────────────────────────────
    // F5 — 프레임이 다른 문서로 바뀐 뒤 옛 번호 거부(stale)
    //
    // 결정적으로 재현하려면 **한 관찰 안에서** 프레임이 바뀌어야 한다. 그래서 한 응답에 동작 두 개를 준다:
    //   ① 프레임을 이동시키는 버튼 클릭  ② 같은 관찰의 옛 번호로 프레임 안 버튼 클릭
    // ②는 이미 사라진 문서의 번호이므로 거부되어야 한다 — 거부되지 않고 "지금 그 자리에 있는 다른 요소"를
    // 누르는 것이 바로 이 검사가 막는 사고다.
    // ───────────────────────────────────────────────────────────────
    {
      // 프레임을 원래 문서로 되돌려 둔다.
      await evalIn(parentPage, `document.getElementById('f1').src = ${JSON.stringify(fx.childOrigin + '/form')}; true`)
      await sleep(1200)
      const r = await run({
        reqId: 'F5', task: '프레임 이동 후 옛 번호',
        script: [
          {
            reply: (c) => {
              const navRef = frameRef(c.lastUser, childHost, '프레임 이동')
              const oldRef = frameRef(c.lastUser, childHost, '프레임 제출')
              return JSON.stringify([
                { action: 'click', ref: navRef },
                { action: 'click', ref: oldRef },
              ])
            },
          },
          { reply: () => '{"action":"done","message":"끝"}' },
        ],
        timeoutMs: 30000,
      })
      const clickResults = r.events.filter((e) => e.type === 'result' && /클릭/.test(String(e.label ?? '')))
